// ---------------------------------------------------------------- the map's lore snippets and landmarks
I18N.add('nl', {
"ui": {},
"content": {
"path": {
"LORE_MARKS.jukebox": { "name": "Kapotte Jukebox" },
"LORE_MARKS.tickets": { "name": "Verloren Kaartjes" },
"LORE_MARKS.hiscore": { "name": "Oud Highscorebord" },
"LORE_MARKS.tower": { "name": "Uitkijktoren" },
"LORE_MARKS.wheel": { "name": "Prijzenrad" },
"LORE_MARKS.slots": { "name": "Geluksgokkast" },
"LORE_MARKS.moles": { "name": "Mollenmeppen" },
"LORE_MARKS.skee": { "name": "Skeeball" },
"LORE_MARKS.petshop": { "name": "Dierenwinkel" },
"LORE_SNIPS.tower": { "0": "Een uitkijktoren. De muntverrekijker bovenop laat alleen gisteren zien.", "1": "Iemand kerfde IK WAS HIER, 1994 in de reling. En ER NOG STEEDS eronder.", "2": "De torenwachter slaapt met één oog op de trap en één op het uitzicht.", "3": "Van daarboven kun je elk brandend lampje op de verdieping tellen. Het zijn er niet veel.", "4": "De lift is kapot. De lift is al kapot sinds voordat er liften bestonden.", "5": "Torens werden gebouwd om naar Crawlers uit te kijken. Nu kijken ze gewoon." },
"LORE_SNIPS.plinko": { "0": "Een Plinkobord. Elk pinnetje is al een miljoen keer geraakt en zegt nog steeds ding.", "1": "De pinnetjes onthouden elk muntje. Ze duimen voor het midden.", "2": "Een sticker op het glas: NIET SCHUDDEN. Iemand heeft er een verdrietig gezichtje op getekend." },
"LORE_SNIPS.wheel": { "0": "Het prijzenrad kraakt. JACKPOT staat expres op het kleinste vak.", "1": "Een rad van fortuin. Fortuin is sinds de laatste stroomstoring niet meer gezien.", "2": "Het klepje is dun gesleten. Het heeft tegen heel veel mensen nee gezegd." },
"LORE_SNIPS.slots": { "0": "Een gokkast met één arm. Hij zwaait toch naar je.", "1": "Drie kersen, een bel en een lampje, draaiend in het donker voor niemand.", "2": "Het uitbetaalbakje is glad gepoetst door vingers die toch even voelen, voor de zekerheid." },
"LORE_SNIPS.moles": { "0": "Mollenmeppen. De mollen zijn jaren geleden lid geworden van de vakbond en willen zachtjes gemept worden.", "1": "Je hoort ze daarbinnen hun opduikers oefenen.", "2": "Een gelamineerd kaartje: DE MOLLEN MAKEN HET GOED. DE MOLLEN ZIJN ACTEURS." },
"LORE_SNIPS.skee": { "0": "Een skeeballbaan. De bekers van 100 worden zo zelden geraakt dat er spinnenwebben in hangen.", "1": "De ballen rollen vanzelf terug. De baan voelt zich eenzaam.", "2": "Iemand kraste een turflijst van perfecte potjes in de reling. Er staat één streepje." },
"LORE_SNIPS.petshop": { "0": "Een dierenwinkel. Elk dier hier was ooit een prijs. Nu willen ze zelf een Crawler.", "1": "Elk hok heeft een naamkaartje. Sommige namen zijn doorgestreept en opnieuw geschreven, groter.", "2": "Een bordje: EEN HUISDIER IS VOOR HET LEVEN, NIET ALLEEN VOOR ÉÉN KLIM." },
"LORE_SNIPS.jukebox": { "0": "Een kapotte jukebox. Hij speelt alleen nog B-kantjes, en alleen voor zichzelf.", "1": "Druk op een willekeurige knop: hetzelfde liedje. Iedereen in de toren kent de tekst.", "2": "De jukebox neuriet het deuntje van de demomodus, vals, als een slaapliedje.", "3": "Iemand legde een kwartje op de jukebox, voor als hij ooit beter wordt." },
"LORE_SNIPS.tickets": { "0": "Een stapel verloren kaartjes, duizenden diep. Niemand kwam ze ooit ophalen.", "1": "Iemand spaarde deze kaartjes een hele zomer lang. De beer die ze wilden, staat nog steeds boven.", "2": "Verloren kaartjes dwarrelen hier van elke verdieping naar beneden, als bladeren.", "3": "Op het bovenste kaartje staat VOOR MAMA in waskrijt. Daarna niets." },
"LORE_SNIPS.hiscore": { "0": "Een oud highscorebord, nog steeds verlicht. Iemand houdt de stekker erin.", "1": "Het highscorebord. De bovenste naam is in jaren niet veranderd.", "2": "Een highscorebord met een gebarsten scherm. De scores gloeien door de barsten heen." }
}
}
});

